    "about.p1": "\u0645\u0646 \u0641\u0627\u0631\u063a\u200c\u0627\u0644\u062a\u062d\u0635\u06cc\u0644 \u0631\u0634\u062a\u0647 \u0645\u0639\u0645\u0627\u0631\u06cc \u0648 \u062f\u0627\u0631\u0627\u06cc \u0645\u062f\u0631\u06a9 \u06a9\u0627\u0631\u0634\u0646\u0627\u0633\u06cc \u0627\u0631\u0634\u062f \u0637\u0631\u0627\u062d\u06cc \u0634\u0647\u0631\u06cc \u0647\u0633\u062a\u0645 \u0648 \u0639\u0644\u0627\u0642\u0647 \u0632\u06cc\u0627\u062f\u06cc \u0628\u0647 \u0637\u0631\u0627\u062d\u06cc \u0645\u062d\u06cc\u0637\u200c\u0647\u0627\u06cc \u067e\u0627\u06cc\u062f\u0627\u0631 \u0648 \u0627\u0646\u0633\u0627\u0646\u200c\u0645\u062d\u0648\u0631 \u062f\u0627\u0631\u0645. \u0645\u062f\u0631\u06a9 \u06a9\u0627\u0631\u0634\u0646\u0627\u0633\u06cc \u0627\u0631\u0634\u062f \u0637\u0631\u0627\u062d\u06cc \u0634\u0647\u0631\u06cc \u062e\u0648\u062f \u0631\u0627 \u0627\u0632 \u062f\u0627\u0646\u0634\u06af\u0627\u0647 \u0646\u06cc\u0648\u06a9\u0627\u0633\u0644 \u062f\u0631 \u0627\u0646\u06af\u0644\u0633\u062a\u0627\u0646 (\u06f2\u06f0\u06f2\u06f5\u2013\u06f2\u06f0\u06f2\u06f6) \u0648 \u0645\u062f\u0631\u06a9 \u06a9\u0627\u0631\u0634\u0646\u0627\u0633\u06cc \u0645\u0639\u0645\u0627\u0631\u06cc \u0631\u0627 \u0627\u0632 \u062f\u0627\u0646\u0634\u06af\u0627\u0647 \u0628\u0627\u0647\u0686\u0647 \u0634\u0647\u06cc\u0631 \u062a\u0631\u06a9\u06cc\u0647 (\u06f2\u06f0\u06f2\u06f1\u2013\u06f2\u06f0\u06f2\u06f5) \u062f\u0631\u06cc\u0627\u0641\u062a \u06a9\u0631\u062f\u0647\u200c\u0627\u0645.",
