    "projects.p3Desc": "\u0627\u06cc\u0646 \u067e\u0631\u0648\u0698\u0647 \u0637\u0631\u062d\u06cc \u0628\u0631\u0627\u06cc \u06cc\u06a9 \u062f\u0627\u0646\u0634\u06a9\u062f\u0647 \u0645\u0639\u0645\u0627\u0631\u06cc \u0627\u0631\u0627\u0626\u0647 \u0645\u06cc\u200c\u062f\u0647\u062f \u06a9\u0647 \u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u0645\u062d\u06cc\u0637\u06cc \u067e\u0648\u06cc\u0627 \u0628\u0631\u0627\u06cc \u06cc\u0627\u062f\u06af\u06cc\u0631\u06cc\u060c \u0647\u0645\u06a9\u0627\u0631\u06cc \u0648 \u062a\u0639\u0627\u0645\u0644 \u0628\u0627 \u062c\u0627\u0645\u0639\u0647 \u0637\u0631\u0627\u062d\u06cc \u0634\u062f\u0647 \u0627\u0633\u062a. \u0627\u06cc\u062f\u0647 \u0627\u0635\u0644\u06cc \u0637\u0631\u0627\u062d\u06cc \u0627\u0632 \u0633\u062a\u0648\u0646 \u0641\u0642\u0631\u0627\u062a \u0627\u0644\u0647\u0627\u0645 \u06af\u0631\u0641\u062a\u0647 \u0634\u062f\u0647\u061b \u0628\u0647\u200c\u06af\u0648\u0646\u0647\u200c\u0627\u06cc \u06a9\u0647 \u0633\u0627\u062e\u062a\u0627\u0631 \u0627\u0635\u0644\u06cc \u0633\u0627\u062e\u062a\u0645\u0627\u0646 \u0628\u0647\u200c\u0635\u0648\u0631\u062a \u0646\u0645\u0627\u06cc\u0627\u0646 \u0628\u0627\u0642\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u062f \u0648 \u0628\u0647 \u0639\u0646\u0635\u0631 \u0645\u0631\u06a9\u0632\u06cc \u0633\u0627\u0632\u0645\u0627\u0646\u200c\u062f\u0647\u0646\u062f\u0647 \u0641\u0636\u0627\u0647\u0627 \u062a\u0628\u062f\u06cc\u0644 \u0645\u06cc\u200c\u0634\u0648\u062f.\n\n\u0645\u0634\u0627\u0628\u0647 \u0633\u0627\u062e\u062a\u0627\u0631 \u0633\u062a\u0648\u0646 \u0641\u0642\u0631\u0627\u062a\u060c \u0641\u0636\u0627\u0647\u0627\u06cc \u0622\u0645\u0648\u0632\u0634\u06cc \u0648 \u0627\u062c\u062a\u0645\u0627\u0639\u06cc \u0628\u0647 \u0627\u06cc\u0646 \u0647\u0633\u062a\u0647 \u0645\u0631\u06a9\u0632\u06cc \u0645\u062a\u0635\u0644 \u0634\u062f\u0647\u200c\u0627\u0646\u062f \u0648 \u062f\u0631 \u0646\u062a\u06cc\u062c\u0647\u060c \u0633\u0644\u0633\u0644\u0647\u200c\u0645\u0631\u0627\u062a\u0628 \u0641\u0636\u0627\u06cc\u06cc \u0645\u0634\u062e\u0635 \u0648 \u0627\u0631\u062a\u0628\u0627\u0637\u0627\u062a \u0628\u0635\u0631\u06cc \u0642\u062f\u0631\u062a\u0645\u0646\u062f\u06cc \u062f\u0631 \u0633\u0631\u0627\u0633\u0631 \u0633\u0627\u062e\u062a\u0645\u0627\u0646 \u0634\u06a9\u0644 \u06af\u0631\u0641\u062a\u0647 \u0627\u0633\u062a. \u062f\u0627\u0646\u0634\u06a9\u062f\u0647 \u0634\u0627\u0645\u0644 \u0627\u0633\u062a\u0648\u062f\u06cc\u0648\u0647\u0627\u06cc \u0637\u0631\u0627\u062d\u06cc\u060c \u06a9\u0644\u0627\u0633\u200c\u0647\u0627\u06cc \u0622\u0645\u0648\u0632\u0634\u06cc\u060c \u06a9\u0627\u0631\u06af\u0627\u0647\u200c\u0647\u0627\u060c \u0622\u0632\u0645\u0627\u06cc\u0634\u06af\u0627\u0647\u200c\u0647\u0627\u06cc \u062f\u06cc\u062c\u06cc\u062a\u0627\u0644\u060c \u06a9\u062a\u0627\u0628\u062e\u0627\u0646\u0647 \u0648 \u0641\u0636\u0627\u0647\u0627\u06cc \u0646\u0645\u0627\u06cc\u0634\u06af\u0627\u0647\u06cc \u0627\u0633\u062a \u06a9\u0647 \u067e\u06cc\u0631\u0627\u0645\u0648\u0646 \u0645\u0633\u06cc\u0631\u0647\u0627\u06cc \u062d\u0631\u06a9\u062a\u06cc \u0628\u0627\u0632 \u0648 \u0641\u0636\u0627\u0647\u0627\u06cc \u06cc\u0627\u062f\u06af\u06cc\u0631\u06cc \u0645\u0634\u062a\u0631\u06a9 \u0633\u0627\u0632\u0645\u0627\u0646\u200c\u062f\u0647\u06cc \u0634\u062f\u0647\u200c\u0627\u0646\u062f.\n\n\u0628\u0627 \u062a\u0631\u06a9\u06cc\u0628 \u0641\u0636\u0627\u0647\u0627\u06cc \u0622\u0645\u0648\u0632\u0634\u06cc \u0648 \u062a\u0639\u0627\u0645\u0644\u0627\u062a \u0639\u0645\u0648\u0645\u06cc\u060c \u0627\u06cc\u0646 \u067e\u0631\u0648\u0698\u0647 \u0645\u062d\u06cc\u0637\u06cc \u0631\u0627 \u0634\u06a9\u0644 \u0645\u06cc\u200c\u062f\u0647\u062f \u06a9\u0647 \u062e\u0644\u0627\u0642\u06cc\u062a\u060c \u0647\u0645\u06a9\u0627\u0631\u06cc \u0648 \u062a\u0628\u0627\u062f\u0644 \u0627\u06cc\u062f\u0647\u200c\u0647\u0627 \u0631\u0627 \u062a\u0642\u0648\u06cc\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f.",
    "projects.w1Title": "\u062f\u0641\u062a\u0631 Architenko",
