    "experience.r1Desc": "\u067e\u06cc\u0634\u0646\u0647\u0627\u062f\u0627\u062a \u0637\u0631\u0627\u062d\u06cc \u0634\u0647\u0631\u06cc\u060c \u062a\u062d\u0644\u06cc\u0644 \u0633\u0627\u06cc\u062a\u060c \u0637\u0631\u0627\u062d\u06cc \u0634\u0647\u0631\u06cc \u0648 \u0645\u062f\u0644\u200c\u0633\u0627\u0632\u06cc \u0633\u0647\u200c\u0628\u0639\u062f\u06cc \u0631\u06cc\u0648\u06cc\u062a \u062f\u0631 \u0646\u06cc\u0648\u06a9\u0627\u0633\u0644\u060c \u0627\u0646\u06af\u0644\u0633\u062a\u0627\u0646.",
