    "experience.r3Desc": "\u0637\u0631\u0627\u062d\u06cc \u062f\u0631\u0648\u0627\u0632\u0647 \u0648\u0631\u0648\u062f\u06cc \u0648 \u0627\u062c\u0632\u0627\u06cc \u0633\u0627\u062e\u062a\u0645\u0627\u0646\u06cc\u060c \u0645\u062f\u0644\u200c\u0647\u0627\u06cc \u0633\u0647\u200c\u0628\u0639\u062f\u06cc\u060c \u0645\u0633\u062a\u0646\u062f\u0627\u062a \u0641\u0646\u06cc \u0648 \u0647\u0645\u0627\u0647\u0646\u06af\u06cc \u0633\u0627\u06cc\u062a \u062f\u0631 \u0628\u0631\u0648\u06a9\u0633\u0644\u060c \u0628\u0644\u0698\u06cc\u06a9.",
